  if (file) {
    const reader = new FileReader();
    reader.onload = (event) => {
      const romData = new Uint8Array(event.target.result);
      chip8.loadROM(romData);
      updateDisplay();
      updateDebugger();
      document.getElementById('status').textContent = `Loaded: ${file.name}`;
    };
    reader.readAsArrayBuffer(file);
  }
});

